"""Command line entry point for order-book-engine."""

from __future__ import annotations

import argparse
import json
import sys

from . import __version__
from . import engine
from .engine import INVALID_JSON, OrderBook, validate_event


def _write_line(stream, payload: str) -> bool:
    try:
        stream.write(payload)
        stream.write("\n")
    except (OSError, ValueError):
        return False
    return True


def _reject(input_line: str, event_id, reason: str, book: dict) -> dict:
    return {
        "input_line": input_line,
        "event_id": event_id,
        "result": "REJECTED",
        "rejection_reason": reason,
        "trades": [],
        "order_book": book,
    }


def replay(stdin, stdout) -> int:
    """Consume UTF-8 JSON Lines from stdin and emit one JSON object per line.

    Returns 0 on clean completion, 1 when reading or writing fails; a single
    ``ERROR_IO`` line is written to stderr on such failures.
    """
    book = OrderBook()
    json_loads = json.loads

    def emit(obj: dict) -> bool:
        return _write_line(
            stdout,
            json.dumps(obj, ensure_ascii=False, separators=(",", ":")),
        )

    try:
        line_iter = iter(stdin)
        while True:
            try:
                raw = next(line_iter)
            except StopIteration:
                break
            except (OSError, UnicodeError):
                sys.stderr.write("ERROR_IO\n")
                return 1

            if raw.endswith(b"\n"):
                raw = raw[:-1]
            if raw.endswith(b"\r"):
                raw = raw[:-1]
            if not raw:
                # Blank lines are ignored.
                continue

            try:
                input_line = raw.decode("utf-8")
            except UnicodeDecodeError:
                sys.stderr.write("ERROR_IO\n")
                return 1

            # Reject non-finite numbers (NaN/Infinity) which Python's json
            # parser accepts by default despite them not being valid JSON.
            try:
                parsed = json_loads(
                    input_line,
                    parse_constant=lambda _value: (_ for _ in ()).throw(
                        ValueError("invalid JSON constant")
                    ),
                )
            except (json.JSONDecodeError, ValueError):
                obj = _reject(input_line, None, INVALID_JSON, book.snapshot())
                if not emit(obj):
                    sys.stderr.write("ERROR_IO\n")
                    return 1
                continue

            event, schema_error = validate_event(parsed)
            if schema_error is not None:
                event_id = parsed.get("event_id") if isinstance(parsed, dict) else None
                if not isinstance(event_id, str):
                    event_id = None
                obj = _reject(
                    input_line, event_id, schema_error, book.snapshot()
                )
                if not emit(obj):
                    sys.stderr.write("ERROR_IO\n")
                    return 1
                continue

            event_id = event["event_id"]
            if event_id in book.event_ids:
                obj = _reject(
                    input_line,
                    event_id,
                    engine.DUPLICATE_EVENT_ID,
                    book.snapshot(),
                )
                if not emit(obj):
                    sys.stderr.write("ERROR_IO\n")
                    return 1
                continue

            if event["kind"] == "ADD":
                order_id = event["order_id"]
                if order_id in book.order_ids:
                    obj = _reject(
                        input_line,
                        event_id,
                        engine.DUPLICATE_ORDER_ID,
                        book.snapshot(),
                    )
                    if not emit(obj):
                        sys.stderr.write("ERROR_IO\n")
                        return 1
                    continue

                book.event_ids.add(event_id)
                book.order_ids.add(order_id)
                status, trades = book.add(
                    order_id,
                    event["side"],
                    event["order_type"],
                    event["quantity"],
                    event["price"],
                )
            else:
                status = book.cancel(event["order_id"])
                if status is None:
                    obj = _reject(
                        input_line,
                        event_id,
                        engine.UNKNOWN_ORDER,
                        book.snapshot(),
                    )
                    if not emit(obj):
                        sys.stderr.write("ERROR_IO\n")
                        return 1
                    continue
                book.event_ids.add(event_id)
                trades = []

            obj = {
                "input_line": input_line,
                "event_id": event_id,
                "result": status,
                "trades": trades,
                "order_book": book.snapshot(),
            }
            if not emit(obj):
                sys.stderr.write("ERROR_IO\n")
                return 1
    except (OSError, ValueError):
        sys.stderr.write("ERROR_IO\n")
        return 1

    try:
        stdout.flush()
    except (OSError, ValueError):
        sys.stderr.write("ERROR_IO\n")
        return 1
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="order-book-engine",
        description="Deterministic limit order book matching and execution analytics",
    )
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")
    sub.add_parser(
        "replay",
        help="replay JSON Lines order events from stdin and emit match results",
    )
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0

    if args.command == "replay":
        return replay(sys.stdin.buffer, sys.stdout)

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

